<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Security;
use EventMenu\Services\OrderFulfillmentService;

if(!Auth::can('orders.fulfill')&&!Auth::can('orders.delivery')&&!Auth::can('orders.view')){http_response_code(403);exit('Sua função não possui permissão para retirada por QR.');}
$tenantId=em_require_tenant();$service=new OrderFulfillmentService();$token=trim((string)($_GET['token']??''));$query=trim((string)($_GET['q']??''));
function pickup_qty(float|int|string$value):string{$qty=(float)$value;if(abs($qty-round($qty))<.0005)return(string)(int)round($qty);return rtrim(rtrim(number_format($qty,3,',','.'),'0'),',');}
function pickup_channel(string$channel):string{return match($channel){'counter'=>'Balcão / PDV','pickup'=>'Retirada no local','delivery'=>'Delivery',default=>$channel};}
function pickup_progress_label(string$status):string{return match($status){'fulfilled'=>'Tudo entregue','partial'=>'Retirada parcial',default=>'Aguardando retirada'};}

if($_SERVER['REQUEST_METHOD']==='POST'){
 em_post_csrf();$action=(string)($_POST['action']??'');
 try{
  if($action==='locate'){$code=trim((string)($_POST['code']??''));try{$normalized=$service->normalizeToken($code);em_go('pickup',['token'=>$normalized]);}catch(Throwable){$matches=$service->search($code,10);if(count($matches)===1)em_go('pickup',['token'=>$matches[0]['public_token']]);em_go('pickup',['q'=>$code]);}}
  if($action==='fulfill'){$normalized=$service->normalizeToken((string)($_POST['token']??''));$details=$service->fulfill($normalized,is_array($_POST['qty']??null)?$_POST['qty']:[],(string)($_POST['batch_key']??''),(string)($_POST['notes']??''));$remaining=pickup_qty($details['progress']['remaining_quantity']??0);$message=($details['progress']['status']??'')==='fulfilled'?'Retirada registrada. Todos os itens foram entregues.':'Retirada parcial registrada. Ainda restam '.$remaining.' item(ns) no pedido.';em_flash('ok',$message);em_go('pickup',['token'=>$normalized]);}
  if($action==='correct'){$normalized=$service->normalizeToken((string)($_POST['token']??''));$qty=(float)str_replace(',','.',(string)($_POST['quantity']??'0'));$service->correct((int)($_POST['fulfillment_id']??0),$qty,(string)($_POST['reason']??''));em_flash('ok','Correção registrada sem apagar o histórico original.');em_go('pickup',['token'=>$normalized]);}
 }catch(Throwable$e){em_flash('error',$e->getMessage());if($token!=='')em_go('pickup',['token'=>$token]);em_go('pickup');}
}
$details=null;if($token!==''){try{$details=$service->detailsByToken($token);$token=(string)$details['order']['public_token'];}catch(Throwable$e){em_flash('error',$e->getMessage());$token='';}}
$matches=[];if(!$details&&$query!==''){try{$matches=$service->search($query,20);}catch(Throwable$e){em_flash('error',$e->getMessage());}}
em_header('Retirada / QR','pickup');
?>
<style>
.pickup-locate{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:8px}.pickup-scanner{margin-top:12px;border:1px solid var(--line);border-radius:16px;padding:10px;background:#111}.pickup-scanner video{display:block;width:100%;max-height:390px;object-fit:cover;border-radius:12px;background:#000}.pickup-item-list{display:grid;gap:10px}.pickup-item{border:1px solid var(--line);border-radius:14px;padding:14px;background:#fff}.pickup-item-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.pickup-item h3{margin:0 0 4px;font-size:16px}.pickup-item-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;margin:12px 0}.pickup-mini{background:var(--panel2);border:1px solid var(--line);border-radius:10px;padding:9px}.pickup-mini span{display:block;font-size:10px;color:var(--muted)}.pickup-mini strong{display:block;font-size:18px;margin-top:3px}.pickup-control{display:grid;grid-template-columns:42px minmax(72px,110px) 42px minmax(100px,1fr);gap:7px;align-items:center}.pickup-control button{min-height:42px}.pickup-control input{text-align:center;font-weight:800}.pickup-ready{color:#23754b}.pickup-wait{color:#a66c14}.pickup-history{display:grid;gap:8px}.pickup-history-row{border:1px solid var(--line);border-radius:12px;padding:12px;background:#fff}.pickup-result{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:9px}.pickup-result a{display:block;border:1px solid var(--line);background:#fff;border-radius:12px;padding:13px}.pickup-result strong{display:block;font-size:15px}.pickup-result span{font-size:11px;color:var(--muted)}
@media(max-width:700px){.pickup-locate{grid-template-columns:1fr 1fr}.pickup-locate input{grid-column:1/-1}.pickup-item-stats{grid-template-columns:1fr 1fr}.pickup-control{grid-template-columns:44px 1fr 44px}.pickup-control .pickup-all{grid-column:1/-1}.pickup-item-head{display:block}.pickup-item-head .status-pill{display:inline-flex;margin-top:8px}}
</style>
<section class="page-hero"><div><span class="eyebrow">CONFERÊNCIA E ENTREGA</span><h2>Retirada por QR</h2><p>Leia o QR ou localize pelo número, nome ou telefone. O sistema libera somente itens pagos e fisicamente disponíveis; entregas parciais mantêm o saldo para a próxima retirada.</p></div><?php if($details):?><div class="hero-actions"><a class="button secondary" target="_blank" href="<?= Security::e(app_url('?route=receipt&id='.(int)$details['order']['id'])) ?>">Imprimir comprovante</a></div><?php endif;?></section>
<section class="card" style="margin-bottom:14px"><div class="section-head"><div><span class="eyebrow">LOCALIZAR</span><h2>QR, pedido ou cliente</h2></div></div><form method="post" class="pickup-locate" id="pickup-locate-form"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="locate"><input id="pickup-code" name="code" required autocomplete="off" placeholder="QR, #123, nome ou telefone"><button type="button" class="secondary" id="pickup-camera">Usar câmera</button><button class="primary">Localizar</button></form><div class="pickup-scanner" id="pickup-scanner" hidden><video id="pickup-video" playsinline muted></video><div class="actions" style="margin-top:8px"><button type="button" class="secondary" id="pickup-stop">Fechar câmera</button></div><p class="muted" id="pickup-scan-status">Aponte a câmera para o QR do pedido.</p></div></section>
<?php if($matches):?><section class="card" style="margin-bottom:14px"><div class="section-head"><h2>Resultados para “<?= Security::e($query) ?>”</h2><span class="badge"><?= count($matches) ?></span></div><div class="pickup-result"><?php foreach($matches as$m):?><a href="<?= Security::e(app_url('?route=pickup&token='.rawurlencode($m['public_token']))) ?>"><strong>Pedido #<?= (int)$m['id'] ?> · <?= Security::e($m['customer_name']?:'Consumidor') ?></strong><span><?= Security::e(pickup_channel((string)$m['channel'])) ?> · <?= Security::e($m['unit_name']?:'Unidade') ?><br><?= Security::e($m['payment_status']) ?> · <?= em_money($m['total_cents']) ?> · <?= Security::e($m['created_at']) ?></span></a><?php endforeach;?></div></section><?php elseif($query!==''&&!$details):?><div class="alert">Nenhum pedido de retirada encontrado para “<?= Security::e($query) ?>”.</div><?php endif;?>
<?php if($details):$order=$details['order'];$progress=$details['progress'];$paid=(string)$order['payment_status']==='paid'||(int)$order['total_cents']===0;$closed=(string)$order['status']==='cancelled';$canFulfill=!$closed&&$paid&&(float)$progress['remaining_quantity']>0&&(float)$progress['available_quantity']>0;?>
<section class="card" style="margin-bottom:14px"><div class="section-head"><div><span class="eyebrow"><?= Security::e(pickup_channel((string)$order['channel'])) ?> · <?= Security::e($order['unit_name']?:'Unidade') ?></span><h2>Pedido #<?= (int)$order['id'] ?></h2><div class="muted"><?= Security::e($order['customer_name']?:'Consumidor') ?><?= $order['customer_phone']?' · '.Security::e($order['customer_phone']):'' ?></div></div><div class="actions"><span class="status-pill <?= ($progress['status']??'')==='fulfilled'?'active':'' ?>"><?= Security::e(pickup_progress_label((string)$progress['status'])) ?></span><span class="status-pill <?= $paid?'active':'suspended' ?>"><?= $paid?'Pagamento confirmado':'Pagamento pendente' ?></span></div></div>
<div class="metric-grid" style="grid-template-columns:repeat(4,minmax(0,1fr))"><div class="metric-card"><span>Pedido</span><strong><?= pickup_qty($progress['ordered_quantity']) ?></strong><small>quantidade total</small></div><div class="metric-card"><span>Produção liberada</span><strong><?= pickup_qty($progress['production_ready_quantity']) ?></strong><small>pronto ou sem produção</small></div><div class="metric-card"><span>Já entregue</span><strong><?= pickup_qty($progress['fulfilled_quantity']) ?></strong><small>líquido após correções</small></div><div class="metric-card"><span>Disponível agora</span><strong><?= pickup_qty($progress['available_quantity']) ?></strong><small>pode ser entregue agora</small></div></div>
<?php if(!$paid&&(int)$order['total_cents']>0):?><div class="alert error"><strong>Não libere produtos.</strong> O pagamento de <?= em_money($order['total_cents']) ?> ainda não foi confirmado.</div><?php elseif((string)$order['status']==='cancelled'):?><div class="alert error">Pedido cancelado. Nenhum item pode ser entregue.</div><?php elseif(($progress['status']??'')==='fulfilled'):?><div class="alert ok">Todos os itens deste pedido já foram entregues.</div><?php elseif((float)$progress['available_quantity']<=0):?><div class="alert">Ainda existem itens no pedido, mas nenhum está liberado para retirada agora. Aguarde cozinha/bar/expedição.</div><?php endif;?>
<form method="post" id="fulfillment-form"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="fulfill"><input type="hidden" name="token" value="<?= Security::e($token) ?>"><input type="hidden" name="batch_key" value="<?= Security::e(bin2hex(random_bytes(16))) ?>"><div class="pickup-item-list"><?php foreach($details['items']as$item):$remaining=(float)$item['remaining_quantity'];$available=(float)$item['available_quantity'];$step=abs((float)$item['ordered_quantity']-round((float)$item['ordered_quantity']))<.0005?'1':'0.001';?><article class="pickup-item"><div class="pickup-item-head"><div><h3><?= Security::e($item['name_snapshot']) ?></h3><?php if(!empty($item['modifiers'])):?><div class="muted"><?php foreach($item['modifiers']as$mod):?><?= Security::e($mod['group_name_snapshot'].': '.$mod['option_name_snapshot']) ?><br><?php endforeach;?></div><?php endif;?><?php if(!empty($item['notes'])):?><div class="muted">Obs.: <?= Security::e($item['notes']) ?></div><?php endif;?></div><span class="status-pill <?= $item['production_status']==='ready'||$item['production_status']==='not_required'?'active':'suspended' ?>"><?= $item['production_status']==='not_required'?'LIBERAÇÃO IMEDIATA':($item['production_status']==='ready'?'PRODUÇÃO PRONTA':'AGUARDANDO PRODUÇÃO') ?></span></div><div class="pickup-item-stats"><div class="pickup-mini"><span>Pedido</span><strong><?= pickup_qty($item['ordered_quantity']) ?></strong></div><div class="pickup-mini"><span>Pronto</span><strong><?= pickup_qty($item['production_ready_quantity']) ?></strong></div><div class="pickup-mini"><span>Entregue</span><strong><?= pickup_qty($item['fulfilled_quantity']) ?></strong></div><div class="pickup-mini"><span>Falta</span><strong><?= pickup_qty($remaining) ?></strong></div></div><?php if($remaining>0):?><div class="pickup-control"><button type="button" class="secondary pickup-minus"<?= $canFulfill&&$available>0?'':' disabled' ?>>−</button><input class="pickup-qty" type="number" name="qty[<?= (int)$item['id'] ?>]" min="0" max="<?= Security::e((string)$available) ?>" step="<?= $step ?>" value="0" data-max="<?= Security::e((string)$available) ?>"<?= $canFulfill&&$available>0?'':' disabled' ?>><button type="button" class="secondary pickup-plus"<?= $canFulfill&&$available>0?'':' disabled' ?>>+</button><button type="button" class="button secondary pickup-all" data-max="<?= Security::e((string)$available) ?>"<?= $canFulfill&&$available>0?'':' disabled' ?>>Tudo disponível (<?= pickup_qty($available) ?>)</button></div><?php else:?><span class="status-pill active">Entregue</span><?php endif;?></article><?php endforeach;?></div><?php if($canFulfill):?><div class="actions" style="margin-top:12px"><button type="button" class="secondary" id="pickup-all-ready">Selecionar tudo que está disponível</button></div><label style="margin-top:12px">Observação desta retirada<textarea name="notes" maxlength="500" placeholder="Opcional: ex. cliente retirou somente parte do pedido"></textarea></label><button class="primary" style="width:100%;margin-top:12px;min-height:50px" onclick="return confirm('Confirmar as quantidades selecionadas como entregues?')">Confirmar retirada selecionada</button><?php endif;?></form></section>
<?php if($details['history']):?><section class="card" style="margin-bottom:14px"><div class="section-head"><div><span class="eyebrow">AUDITORIA</span><h2>Histórico de retiradas</h2></div></div><div class="pickup-history"><?php foreach($details['history']as$row):$valid=max(0,(float)$row['quantity']-(float)$row['corrected_quantity']);?><article class="pickup-history-row"><div class="section-head"><div><strong><?= Security::e($row['name_snapshot']) ?> · <?= pickup_qty($row['quantity']) ?></strong><br><span class="muted"><?= Security::e($row['created_at']) ?> · <?= Security::e($row['fulfilled_by_name']?:'Usuário') ?></span></div><?php if((float)$row['corrected_quantity']>0):?><span class="status-pill suspended">Corrigido <?= pickup_qty($row['corrected_quantity']) ?></span><?php endif;?></div><?php if($row['notes']):?><p class="muted"><?= Security::e($row['notes']) ?></p><?php endif;?><?php if(Auth::can('orders.fulfillment_correct')&&$valid>.0005):?><details><summary class="button secondary compact">Corrigir lançamento</summary><form method="post" class="form-grid" style="margin-top:10px"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="correct"><input type="hidden" name="token" value="<?= Security::e($token) ?>"><input type="hidden" name="fulfillment_id" value="<?= (int)$row['id'] ?>"><label>Quantidade a estornar<input name="quantity" type="number" min="0.001" max="<?= Security::e((string)$valid) ?>" step="0.001" value="<?= Security::e((string)$valid) ?>" required></label><label class="span-2">Motivo obrigatório<input name="reason" maxlength="500" required placeholder="Ex.: lançado 19 por engano; cliente retirou 1"></label><button class="danger span-2" onclick="return confirm('Registrar correção? O histórico original será preservado.')">Registrar correção auditada</button></form></details><?php endif;?></article><?php endforeach;?></div></section><?php endif;?>
<?php if($details['corrections']):?><section class="card"><div class="section-head"><h2>Correções registradas</h2><span class="badge"><?= count($details['corrections']) ?></span></div><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Item</th><th>Qtd.</th><th>Aprovado por</th><th>Motivo</th></tr></thead><tbody><?php foreach($details['corrections']as$c):?><tr><td><?= Security::e($c['created_at']) ?></td><td><?= Security::e($c['name_snapshot']) ?></td><td><?= pickup_qty($c['quantity']) ?></td><td><?= Security::e($c['approved_by_name']) ?></td><td><?= Security::e($c['reason']) ?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?>
<?php endif;?>
<script>
document.querySelectorAll('.pickup-all').forEach(btn=>btn.addEventListener('click',()=>{const input=btn.parentElement?.querySelector('.pickup-qty');if(input)input.value=btn.dataset.max||'0'}));document.querySelectorAll('.pickup-plus').forEach(btn=>btn.addEventListener('click',()=>{const input=btn.parentElement?.querySelector('.pickup-qty');if(!input)return;const step=parseFloat(input.step||'1'),max=parseFloat(input.dataset.max||'0'),now=parseFloat(input.value||'0');input.value=String(Math.min(max,Math.round((now+step)*1000)/1000))}));document.querySelectorAll('.pickup-minus').forEach(btn=>btn.addEventListener('click',()=>{const input=btn.parentElement?.querySelector('.pickup-qty');if(!input)return;const step=parseFloat(input.step||'1'),now=parseFloat(input.value||'0');input.value=String(Math.max(0,Math.round((now-step)*1000)/1000))}));document.getElementById('pickup-all-ready')?.addEventListener('click',()=>document.querySelectorAll('.pickup-qty').forEach(input=>{if(!input.disabled)input.value=input.dataset.max||'0'}));
(()=>{const button=document.getElementById('pickup-camera'),stopButton=document.getElementById('pickup-stop'),shell=document.getElementById('pickup-scanner'),video=document.getElementById('pickup-video'),status=document.getElementById('pickup-scan-status'),input=document.getElementById('pickup-code'),form=document.getElementById('pickup-locate-form');let stream=null,running=false,detector=null;const stop=()=>{running=false;if(stream){stream.getTracks().forEach(track=>track.stop());stream=null}if(video)video.srcObject=null;if(shell)shell.hidden=true};async function scan(){if(!running||!detector||!video)return;try{const codes=await detector.detect(video);const value=codes?.[0]?.rawValue;if(value){input.value=value;stop();form.requestSubmit();return}}catch{}if(running)requestAnimationFrame(scan)}button?.addEventListener('click',async()=>{if(!('BarcodeDetector'in window)||!navigator.mediaDevices?.getUserMedia){status.textContent='Leitor integrado não disponível. Use a câmera normal do celular.';shell.hidden=false;return}try{detector=new BarcodeDetector({formats:['qr_code']});stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});video.srcObject=stream;shell.hidden=false;await video.play();running=true;status.textContent='Aponte a câmera para o QR do pedido.';requestAnimationFrame(scan)}catch{status.textContent='Não foi possível abrir a câmera. Verifique a permissão do navegador.';shell.hidden=false}});stopButton?.addEventListener('click',stop);document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()})})();
</script><?php em_footer();
